function home(){
 const realPosts=posts.filter(post=>!post[5]);
 const projectIds=['research-3059','business-1994','academic-3093'];
 const projects=projectIds.map(id=>realPosts.find(post=>post[0]===id)).filter(Boolean);
 const recentNews=realPosts.filter(post=>['notice','press','newsletter'].includes(post[1])).sort((a,b)=>b[2].localeCompare(a[2])).slice(0,3);
 const projectLink=post=>U('research',{id:post[0]});
 const typeName=post=>{const type=types.find(item=>item[0]===post[1]);return type?T(type[1],type[2]):''};
 const fieldPanels=homeFields.map((field,index)=>{
  const slot=`expertise-${index+1}`;
  const media=field.image
   ?`<img src="assets/${E(field.image)}" alt="${E(T(field.altK,field.altE))}" width="${field.width||2560}" height="${field.height||1440}" loading="${index===0?'eager':'lazy'}" decoding="async">`
   :`<div class="studio-field-slate" role="img" aria-label="${E(T(field.altK,field.altE))}"><span class="studio-field-slate-label">${index===2?'MODELLING / FORECAST':'AI / REMOTE SENSING'}</span><div class="studio-field-slate-terms">${(en?field.termsE:field.termsK).map((term,n)=>`<span><small>0${n+1}</small><strong>${E(term)}</strong></span>`).join('')}</div><small class="studio-field-ready">${T('분야 영상 준비 중','FIELD FILM IN PREPARATION')}</small></div>`;
  return `<section class="studio-field-panel" id="home-field-panel-${field.id}" role="tabpanel" aria-labelledby="home-field-tab-${field.id}" data-home-panel="${field.id}" ${index?'hidden':''}><figure class="studio-field-media" data-production-slot="${slot}" data-film-slot="${slot}" data-film-loop="true">${media}${field.image?`<figcaption>${T(field.noteK,field.noteE)}</figcaption>`:''}</figure><div class="studio-field-copy"><p class="eyebrow">0${index+1} / ${E(T(field.labelK,field.labelE))}</p><h3>${E(T(field.titleK,field.titleE))}</h3><p>${E(T(field.bodyK,field.bodyE))}</p><ul>${(en?field.termsE:field.termsK).map(term=>`<li>${E(term)}</li>`).join('')}</ul>${A(U('business',{axis:field.axis}),'관련 기술 살펴보기','Explore related technologies','plain-arrow')}</div></section>`;
 }).join('');
 const projectCard=(post,index)=>`<a class="studio-project-record ${index===0?'studio-project-record--primary':''}" href="${projectLink(post)}"><span class="studio-project-number">0${index+1}</span><span class="studio-project-type">${E(typeName(post))}${post[5]?T(' · 목업',' · MOCKUP'):''}</span><h3>${E(T(post[3],post[4]))}</h3><time datetime="${E(post[2])}">${E(post[2])}</time><span class="studio-project-arrow" aria-hidden="true">→</span></a>`;
 return `
<section class="landscape-hero" data-production-slot="geosr-hero" data-motion-lab-hero>
 <div class="landscape-film" data-production-slot="geosr-hero" data-film-slot="geosr-hero" data-higgsfield-slot="geosr-hero" data-parallax-surface aria-label="${T('지구 영상 배경','Earth film background')}"><img class="landscape-image" src="assets/concepts/corporate-film/hero-earth-00s-v4.png" data-media-poster="assets/concepts/corporate-film/hero-earth-00s-v4.png" width="2560" height="1440" alt="${E(T('NASA Blue Marble 지형 자료를 바탕으로 표현한 동아시아 방향의 지구 이미지','Earth viewed from space toward East Asia, rendered from NASA Blue Marble terrain'))}" fetchpriority="high"></div>
 <div class="landscape-vignette" aria-hidden="true"></div>
 <div class="landscape-title"><p class="landscape-label">GEOSYSTEM RESEARCH</p><h1>Geo Data<br>Intelligence</h1><p class="landscape-message">${T('지구를 관측하고 변화를 예측합니다','We observe the Earth and forecast change')}</p></div>
 <div class="home-progress" aria-label="${T('관측, 분석, 모델, 예측, 적용','Observation, analysis, model, forecast, apply')}"><span class="home-progress-line" aria-hidden="true"></span><ol>${researchStages.map(stage=>`<li>${T(stage.title,stage.titleE)}</li>`).join('')}</ol></div>
 <p class="landscape-film-status" role="status">${T('영상 준비 중','FILM IN PREPARATION')}</p>
 <button type="button" class="landscape-motion" data-film-toggle="geosr-hero" aria-label="${T('영상 일시정지','Pause film')}" aria-pressed="false" hidden>Ⅱ</button>
</section>
<section class="studio-expertise" id="expertise"><div class="studio-section-heading"><p class="eyebrow">01 / GEOSR EXPERTISE</p><div><h2>${T('현장에서 시작해<br>새로운 이해로','From the field<br>to new understanding')}</h2><p>${T('바다와 하천에서 얻은 자료를 분석하고<br>수치모델과 AI로 환경 변화를 연구합니다','We collect field data from marine and river environments and study them through analysis, modelling and AI')}</p></div>${A(U('business'),'기술과 솔루션','Explore our technologies','plain-arrow')}</div><div class="studio-field-stage"><div class="studio-field-tabs" role="tablist" aria-orientation="horizontal" aria-label="${T('전문 분야 선택','Select an area of expertise')}">${homeFields.map((field,index)=>`<button type="button" id="home-field-tab-${field.id}" role="tab" aria-controls="home-field-panel-${field.id}" aria-selected="${index===0}" tabindex="${index===0?0:-1}" data-home-field="${field.id}"><span>0${index+1}</span><strong>${T(field.labelK,field.labelE)}</strong><small>${['OBSERVE','ANALYSE','PREDICT','DISCOVER'][index]}</small></button>`).join('')}</div><div class="studio-field-panels">${fieldPanels}</div><div class="studio-explorer-foot"><span>GEOSR / EXPERTISE EXPLORER</span><span>${T('분야를 선택해 기술을 살펴보세요','Select a discipline to explore')}</span></div></div></section>
<section class="studio-projects" id="projects"><div class="studio-section-heading"><p class="eyebrow">02 / RESEARCH & PROJECTS</p><div><h2>${T('주요 연구와 수행 사례','Selected research and projects')}</h2></div>${A(U('research'),'연구와 성과 보기','Browse research and results','plain-arrow')}</div><div class="studio-project-grid">${projects.map(projectCard).join('')}</div></section>
<section class="studio-platforms" id="platforms"><div class="studio-section-heading"><p class="eyebrow">03 / DIGITAL PLATFORMS</p><div><h2>${T('데이터를 이해하는<br>두 가지 방법','Two perspectives<br>on environmental data')}</h2><p>${T('분야별 분석을 위한 AX Platform과<br>지구 환경 자료를 탐색하는 GeoDAP','AX Platform for specialist analysis<br>GeoDAP for exploring Earth data')}</p></div></div><div class="studio-platform-grid"><article class="studio-platform-panel studio-platform-panel--ax"><div class="studio-platform-copy"><p class="eyebrow">APPLIED INTELLIGENCE</p><h3>AX<span>Platform</span></h3><p>${T('해양·환경 분야의 탐지와 예측을 지원합니다','Supports detection and forecasting for marine and environmental work')}</p><ul><li>Detect</li><li>Predict</li><li>Monitor</li></ul>${A(U('ax-platform'),'AX Platform 소개','Explore AX Platform','plain-arrow')}</div><figure class="studio-platform-visual studio-platform-visual--ax" data-film-slot="ax-concept-film"><figcaption>AX PLATFORM / CAPABILITIES</figcaption><img src="assets/concepts/ax-detection-v3/ax-detect-end.png" alt="${T('해상 시설물 탐지를 설명하는 생성형 콘셉트 이미지','Generated illustration of marine facility detection')}" loading="lazy"><strong>Detect<br>Predict<br>Monitor</strong><small>${T('콘셉트 이미지 · 소개 영상 준비 중','CONCEPT IMAGE · FILM IN PREPARATION')}</small></figure></article><article class="studio-platform-panel studio-platform-panel--dap"><div class="studio-platform-copy"><p class="eyebrow">EARTH DATA PLATFORM</p><h3>GeoDAP</h3><p>Earth Data Intelligence</p><p>${T('관측·모델·위성 자료를 탐색하는 독립 서비스입니다','An independent service for exploring observation, model and satellite data')}</p><a class="plain-arrow" href="https://www.geo-dap.com/" target="_blank" rel="noopener">${T('GeoDAP 서비스 열기','Open GeoDAP')} <span aria-hidden="true">↗</span></a></div><a class="studio-platform-visual studio-platform-visual--dap" href="https://www.geo-dap.com/" target="_blank" rel="noopener" aria-label="${T('GeoDAP 서비스 열기','Open GeoDAP')}" ><img src="assets/platform-geodap.png" alt="${T('GeoDAP 서비스 화면','GeoDAP service screen')}" loading="lazy" decoding="async"><span class="studio-platform-caption">${T('GeoDAP 서비스 화면','GEODAP SERVICE SCREEN')}</span></a></article></div></section>
${credentialGallery(false)}
<section class="studio-news" id="news"><div class="studio-section-heading"><p class="eyebrow">05 / NEWSROOM</p><div><h2>${T('GeoSR 소식','GeoSR News')}</h2></div>${A(U('news'),'GeoSR 소식 전체 보기','Browse all GeoSR news','plain-arrow')}</div><div class="studio-news-list">${recentNews.map(post=>`<a class="studio-news-record" href="${U('news',{id:post[0]})}"><span class="studio-news-type">${E(typeName(post))}</span><h3>${E(T(post[3],post[4]))}<small>${post[5]?T('목업','MOCKUP'):T('원문 기반','SOURCE RECORD')}</small></h3><time datetime="${E(post[2])}">${E(post[2])}</time><span class="studio-news-arrow" aria-hidden="true">→</span></a>`).join('')}</div></section>`;
}

